leted"},"tags":[]},"outputs":[],"source":["# Data Preparation\n","\n","# Approximate MET values for a variety of light, moderate, and vigorous \n","# activities. See chart for comparism,\n","\n","tod_intensity <- mets %>% \n","mutate(activity_intensity = case_when(mets_pro_mins < 3 ~ 'light', mets_pro_mins >= 3 & mets_pro_mins <= 6 ~ 'moderate', mets_pro_mins > 6  ~ 'vigorous', TRUE ~ 'other')) %>%\n","select(time_of_day, mets_pro_mins, activity_intensity) %>%\n","filter(mets_pro_mins > 0) %>%\n","group_by(time_of_day, activity_intensity) %>%\n","count(activity_intensity)  %>%\n","arrange(-n)\n"]},{"cell_type":"code","execution_count":16,"id":"94083d7b","metadata":{"execution":{"iopub.execute_input":"2025-12-17T22:20:50.099189Z","iopub.status.busy":"2025-12-17T22:20:50.097772Z","iopub.status.idle":"2025-12-17T22:20:50.125476Z","shell.execute_reply":"2025-12-17T22:20:50.123738Z"},"papermill":{"duration":0.040079,"end_time":"2025-12-17T22:20:50.128078","exception":false,"start_time":"2025-12-17T22:20:50.087999","status":"completed"},"tags":[]},"outputs":[{"data":{"text/html":["<table class=\"dataframe\">\n","<caption>A grouped_df: 6 × 3</caption>\n","<thead>\n","\t<tr><th scope=col>time_of_day</th><th scope=col>activity_intensity</th><th scope=col>n</th></tr>\n","\t<tr><th scope=col>&lt;chr&gt;</th><th scope=col>&lt;chr&gt;</th><th scope=col>&lt;int&gt;</th></tr>\n","</thead>\n","<tbody>\n","\t<tr><td>Night    </td><td>light   </td><td>460714</td></tr>\n","\t<tr><td>Morning  </td><td>light   </td><td>303082</td></tr>\n","\t<tr><td>Afternoon</td><td>light   </td><td>293823</td></tr>\n","\t<tr><td>Evening  </td><td>light   </td><td>144878</td></tr>\n","\t<tr><td>Night    </td><td>moderate</td><td> 18913</td></tr>\n","\t<tr><td>Afternoon</td><td>moderate</td><td> 17617</td></tr>\n","</tbody>\n","</table>\n"],"text/latex":["A grouped\\_df: 6 × 3\n","\\begin{tabular}{lll}\n"," time\\_of\\_day & activity\\_intensity & n\\\\\n"," <chr> & <chr> & <int>\\\\\n","\\hline\n","\t 